@php($details=old('details',$pemeriksaan->exists?$pemeriksaan->details->toArray():[['bahan_id'=>'','jumlah_diperiksa'=>'','jumlah_baik'=>'','jumlah_rusak'=>'','alasan'=>'']]))<div id="considerRows">@foreach($details as $i=>$d)<div class="row g-2 mb-2 consider-row"><div class="col-md-4"><select name="details[{{ $i }}][bahan_id]" class="form-select" required>@foreach($bahans as $b)<option value="{{ $b->id }}" @selected(($d['bahan_id']??null)==$b->id)>{{ $b->nama }}</option>@endforeach</select></div>@foreach(['jumlah_diperiksa'=>'Diperiksa','jumlah_baik'=>'Baik','jumlah_rusak'=>'Rusak'] as $f=>$p)<div class="col"><input type="number" step="any" min="0" name="details[{{ $i }}][{{ $f }}]" class="form-control" value="{{ $d[$f]??'' }}" placeholder="{{ $p }}" required></div>@endforeach<div class="col-md-2"><input name="details[{{ $i }}][alasan]" class="form-control" value="{{ $d['alasan']??'' }}" placeholder="Alasan"></div><div class="col"><button type="button" class="btn btn-outline-danger remove-consider">×</button></div></div>@endforeach</div><button type="button" id="addConsider" class="btn btn-sm btn-outline-secondary mb-3">Tambah Baris</button><div><button class="btn btn-primary">Simpan Draft</button></div></form></div></div>
<template id="considerTemplate"><div class="row g-2 mb-2 consider-row"><div class="col-md-4"><select data-name="bahan_id" class="form-select" required>@foreach($bahans as $b)<option value="{{ $b->id }}">{{ $b->nama }}</option>@endforeach</select></div>@foreach(['jumlah_diperiksa'=>'Diperiksa','jumlah_baik'=>'Baik','jumlah_rusak'=>'Rusak'] as $f=>$p)<div class="col"><input type="number" step="any" min="0" data-name="{{ $f }}" class="form-control" placeholder="{{ $p }}" required></div>@endforeach<div class="col-md-2"><input data-name="alasan" class="form-control" placeholder="Alasan"></div><div class="col"><button type="button" class="btn btn-outline-danger remove-consider">×</button></div></div></template>
@push('scripts')<script>let cIndex={{ count($details) }};document.querySelector('#addConsider').onclick=()=>{let n=document.querySelector('#considerTemplate').content.cloneNode(true);n.querySelectorAll('[data-name]').forEach(e=>e.name=`details[${cIndex}][${e.dataset.name}]`);document.querySelector('#considerRows').append(n);cIndex++};document.addEventListener('click',e=>{if(e.target.classList.contains('remove-consider')&&document.querySelectorAll('.consider-row').length>1)e.target.closest('.consider-row').remove()});</script>@endpush
